const state = {};
function bySection(section){ return PRACTICE_ITEMS.filter(x => x.section === section); }
function renderAllPractice(){ document.querySelectorAll('.practice-shell').forEach(shell => renderPractice(shell.dataset.section)); }
function getVisibleItems(section){ const items = bySection(section); const page = state[section]?.page || 0; return items.slice(page*3, page*3+3); }
function renderPractice(section){
  const shell = document.querySelector(`#practice-${CSS.escape(section)} .practice-root`); if(!shell) return;
  const items = bySection(section); if(!state[section]) state[section] = {page:0, answers:{}, revealed:{}};
  const maxPage = Math.max(0, Math.ceil(items.length/3)-1); if(state[section].page > maxPage) state[section].page = maxPage;
  const page = state[section].page; const visible = items.slice(page*3, page*3+3);
  shell.innerHTML = `<div class="practice-top"><span class="progress-pill">Items ${page*3+1}-${Math.min(page*3+3, items.length)} of ${items.length}</span><span class="progress-pill">Page ${page+1} / ${maxPage+1}</span></div><div class="practice-items"></div><div class="controls"><button class="btn secondary" data-action="prev">Previous</button><button class="btn" data-action="check">Check Page</button><button class="btn warn" data-action="reset">Reset Page</button><button class="btn secondary" data-action="next">Next Page</button></div>`;
  const box = shell.querySelector('.practice-items');
  visible.forEach((it, idx)=>{
    const item = document.createElement('fieldset'); item.className='practice-item'; item.dataset.itemId=it.item_id;
    const opts = [['A',it.option_a],['B',it.option_b],['C',it.option_c]];
    item.innerHTML = `<legend>${it.item_id}. ${escapeHtml(it.prompt)}</legend>` + opts.map(([label,val])=>`<label class="option"><input type="radio" name="${it.item_id}" value="${escapeHtml(val)}" ${state[section].answers[it.item_id]===val?'checked':''}>${label}. ${escapeHtml(val)}</label>`).join('') + `<div class="feedback" hidden></div>`;
    box.appendChild(item);
  });
  shell.querySelectorAll('input[type=radio]').forEach(r=> r.addEventListener('change', ev=>{ const fs=ev.target.closest('.practice-item'); state[section].answers[fs.dataset.itemId]=ev.target.value; }));
  shell.querySelector('[data-action=prev]').disabled = page===0;
  shell.querySelector('[data-action=next]').disabled = page===maxPage;
  shell.querySelector('[data-action=prev]').onclick=()=>{state[section].page--; renderPractice(section)};
  shell.querySelector('[data-action=next]').onclick=()=>{state[section].page++; renderPractice(section)};
  shell.querySelector('[data-action=reset]').onclick=()=>{ visible.forEach(it=>{delete state[section].answers[it.item_id]; delete state[section].revealed[it.item_id];}); renderPractice(section); };
  shell.querySelector('[data-action=check]').onclick=()=>checkPage(section);
}
function checkPage(section){
  const visible = getVisibleItems(section);
  visible.forEach(it=>{
    const fs = document.querySelector(`fieldset[data-item-id="${CSS.escape(it.item_id)}"]`);
    const fb = fs.querySelector('.feedback'); const ans = state[section].answers[it.item_id];
    fb.hidden=false; fb.className='feedback';
    if(!ans){ fb.classList.add('no'); fb.textContent='Choose one answer.'; return; }
    if(ans === it.correct_answer){ fb.classList.add('ok'); fb.textContent=it.correct_feedback || `Correct answer: ${it.correct_answer}`; }
    else { fb.classList.add('no'); fb.innerHTML = `${escapeHtml(it.try_again_feedback || 'Try again.')} <span class="inline-actions"><button class="btn light try-again">Try again</button><button class="btn light show-answer">Correct Answer</button></span><span class="answer-text" hidden> ${escapeHtml(it.correct_feedback || ('Correct answer: '+it.correct_answer))}</span>`;
      fb.querySelector('.try-again').onclick=()=>{delete state[section].answers[it.item_id]; renderPractice(section)};
      fb.querySelector('.show-answer').onclick=()=>{fb.querySelector('.answer-text').hidden=false;};
    }
  });
}
function escapeHtml(str){ return String(str).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
function setupModal(){ const modal=document.querySelector('.modal'); if(!modal) return; const img=modal.querySelector('img'); const title=modal.querySelector('.modal-title'); document.querySelectorAll('.zoom').forEach(btn=>{ btn.addEventListener('click',()=>{ img.src=btn.dataset.img; img.alt=btn.dataset.title; title.textContent=btn.dataset.title; modal.classList.add('open'); });}); modal.querySelector('.close-modal').onclick=()=>modal.classList.remove('open'); modal.addEventListener('click',e=>{ if(e.target===modal) modal.classList.remove('open'); }); document.addEventListener('keydown',e=>{ if(e.key==='Escape') modal.classList.remove('open'); }); }
document.addEventListener('DOMContentLoaded',()=>{ renderAllPractice(); setupModal(); });

function initNativeImageZoom() {
  document.querySelectorAll('.flw-native .zoom[data-img]').forEach(btn => {
    if (btn.dataset.nativeZoomReady === '1') return;
    btn.dataset.nativeZoomReady = '1';
    btn.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      const root = btn.closest('.flw-native') || document;
      let modal = root.querySelector('.image-modal');
      let image = modal ? modal.querySelector('#modal-img, img') : null;
      let caption = modal ? modal.querySelector('#modal-cap, .modal-title') : null;
      if (!modal || !image) {
        modal = document.querySelector('.modal');
        image = modal ? modal.querySelector('img') : null;
        caption = modal ? modal.querySelector('.modal-title') : null;
      }
      if (!modal || !image) return;
      image.src = btn.dataset.img || '';
      image.alt = btn.dataset.title || btn.getAttribute('aria-label') || '';
      if (caption) caption.textContent = btn.dataset.title || '';
      modal.classList.add('open');
      modal.setAttribute('aria-hidden', 'false');
    });
  });
  document.querySelectorAll('.flw-native .image-modal, .flw-native .modal').forEach(modal => {
    if (modal.dataset.nativeCloseReady === '1') return;
    modal.dataset.nativeCloseReady = '1';
    const close = () => {
      modal.classList.remove('open');
      modal.setAttribute('aria-hidden', 'true');
    };
    modal.querySelectorAll('.modal-close, .close-modal').forEach(btn => {
      btn.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        close();
      });
    });
    modal.addEventListener('click', event => {
      if (event.target === modal) close();
    });
  });
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initNativeImageZoom);
} else {
  initNativeImageZoom();
}

function initVideoPosters() {
  document.querySelectorAll('.flw-native .video-card video').forEach(video => {
    if (video.dataset.posterReady === '1') return;
    video.dataset.posterReady = '1';
    const card = video.closest('.video-card');
    if (!card) return;
    let shell = video.closest('.flw-video-shell');
    if (!shell) {
      shell = document.createElement('div');
      shell.className = 'flw-video-shell';
      video.parentNode.insertBefore(shell, video);
      shell.appendChild(video);
    }
    const posterSrc = video.getAttribute('poster');
    if (!posterSrc) return;
    const poster = document.createElement('button');
    poster.type = 'button';
    poster.className = 'flw-video-poster';
    poster.setAttribute('aria-label', video.getAttribute('aria-label') || 'Play video');
    const image = document.createElement('img');
    image.src = posterSrc;
    image.alt = '';
    poster.appendChild(image);
    shell.appendChild(poster);
    const hidePoster = () => card.classList.add('is-started', 'is-playing');
    poster.addEventListener('click', () => {
      hidePoster();
      video.play().catch(() => card.classList.remove('is-playing'));
    });
    video.addEventListener('play', hidePoster);
    video.addEventListener('pause', () => card.classList.remove('is-playing'));
    video.addEventListener('ended', () => card.classList.remove('is-playing'));
  });
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initVideoPosters);
} else {
  initVideoPosters();
}
(() => {
  const hiddenLabelCmIds = [623,624,625,626,627,628,629,630,631,632,633,634];
  const tidyCourseIndex = () => {
    hiddenLabelCmIds.forEach((cmid) => {
      const item = document.getElementById(`course-index-cm-${cmid}`);
      if (item) {
        item.remove();
      }
    });
    document.querySelectorAll('#course-index .courseindex-section').forEach((section) => {
      const content = section.querySelector('.courseindex-sectioncontent');
      if (!content) {
        return;
      }
      if (!content.querySelector('li.courseindex-item')) {
        content.classList.remove('show');
        content.setAttribute('hidden', 'hidden');
        const chevron = section.querySelector('.courseindex-chevron');
        if (chevron) {
          chevron.remove();
        }
      }
    });
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', tidyCourseIndex);
  } else {
    tidyCourseIndex();
  }
  const observer = new MutationObserver(tidyCourseIndex);
  observer.observe(document.documentElement, {childList: true, subtree: true});
})();